<template>
  <div class="app-shell"><header class="topbar"><BrandLogo compact /><nav><RouterLink to="/">秒杀广场</RouterLink><RouterLink class="active" to="/orders">我的订单</RouterLink></nav><div class="user-area"><span class="avatar">{{ userInitial }}</span><span>{{ user.username || '用户' }}</span><button type="button" @click="handleLogout">退出</button></div></header>
    <main class="orders-content"><div class="page-heading"><div><p class="eyebrow">ACCOUNT CENTER</p><h1>我的订单</h1><span>查看你的秒杀订单与交易状态</span></div><RouterLink class="back-market" to="/"><svg viewBox="0 0 24 24" fill="none"><path d="M5 12h14M13 6l6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>回到秒杀广场</RouterLink></div>
      <div class="tabs"><button v-for="tab in tabs" :key="tab.value" type="button" :class="{ active: statusFilter === tab.value }" @click="statusFilter = tab.value">{{ tab.label }}<span v-if="tab.value === 'all'">{{ total }}</span></button></div>
      <p v-if="errorMessage" class="page-error">{{ errorMessage }} <button type="button" @click="loadOrders">重新加载</button></p>
      <div v-if="loading" class="orders-panel"><div v-for="n in 3" :key="n" class="order-skeleton"><i></i><i></i><i></i></div></div>
      <div v-else-if="filteredOrders.length" class="orders-panel"><article v-for="order in filteredOrders" :key="order.id || order.orderNo" class="order-row"><div class="order-main"><div class="order-icon">⚡</div><div><h2>秒杀商品 #{{ order.productId || '--' }}</h2><p>订单号：{{ order.orderNo || '--' }}</p><time>{{ formatDate(order.createTime) }}</time></div></div><div class="order-price"><span>实付金额</span><strong>¥{{ formatPrice(order.payAmount) }}</strong></div><div class="order-status" :class="statusClass(order.orderStatus)"><i></i>{{ statusLabel(order.orderStatus) }}</div><button class="detail-button" type="button" @click="openOrder(order)">查看详情<svg viewBox="0 0 24 24" fill="none"><path d="m9 18 6-6-6-6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></button></article></div>
      <div v-else class="empty-card"><div class="empty-icon">📦</div><h2>还没有相关订单</h2><p>去秒杀广场看看，下一件心仪好物正在等你。</p><RouterLink to="/">浏览活动</RouterLink></div>
      <div v-if="totalPages > 1" class="pagination"><button type="button" :disabled="page === 1" @click="page--; loadOrders()">上一页</button><span>第 {{ page }} / {{ totalPages }} 页</span><button type="button" :disabled="page >= totalPages" @click="page++; loadOrders()">下一页</button></div>
    </main>
    <Transition name="modal"><div v-if="selectedOrder" class="modal-backdrop" @click.self="selectedOrder = null"><div class="order-modal"><button class="close-button" type="button" aria-label="关闭" @click="selectedOrder = null">×</button><p class="eyebrow">ORDER DETAIL</p><h2>订单详情</h2><dl><div><dt>订单号</dt><dd>{{ selectedOrder.orderNo || '--' }}</dd></div><div><dt>商品编号</dt><dd>{{ selectedOrder.productId || '--' }}</dd></div><div><dt>购买数量</dt><dd>{{ selectedOrder.quantity || 1 }}</dd></div><div><dt>实付金额</dt><dd class="highlight">¥{{ formatPrice(selectedOrder.payAmount) }}</dd></div><div><dt>订单状态</dt><dd>{{ statusLabel(selectedOrder.orderStatus) }}</dd></div><div><dt>创建时间</dt><dd>{{ formatDate(selectedOrder.createTime) }}</dd></div></dl></div></div></Transition>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import BrandLogo from '../components/BrandLogo.vue'
import { getOrders } from '../api/order'
import { logout } from '../api/auth'
import { clearSession, getCurrentUser } from '../utils/auth'

const router = useRouter(); const user = getCurrentUser(); const userInitial = computed(() => (user.username || 'U').slice(0, 1).toUpperCase()); const orders = ref([]); const loading = ref(false); const errorMessage = ref(''); const page = ref(1); const total = ref(0); const size = 10; const statusFilter = ref('all'); const selectedOrder = ref(null)
const tabs = [{ value: 'all', label: '全部订单' }, { value: 0, label: '待支付' }, { value: 1, label: '已支付' }, { value: 2, label: '已取消' }]
const filteredOrders = computed(() => statusFilter.value === 'all' ? orders.value : orders.value.filter((order) => order.orderStatus === statusFilter.value))
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / size)))
function formatPrice(value) { return Number(value || 0).toFixed(2) }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '--' }
function statusLabel(value) { return ({ 0: '待支付', 1: '已支付', 2: '已取消', 3: '已退款' })[value] || '处理中' }
function statusClass(value) { return ({ 0: 'waiting', 1: 'paid', 2: 'cancelled', 3: 'cancelled' })[value] || 'waiting' }
async function loadOrders() { loading.value = true; errorMessage.value = ''; try { const response = await getOrders({ page: page.value, size, userId: user.userId }); orders.value = response.data?.records || []; total.value = response.data?.total || orders.value.length } catch (error) { errorMessage.value = error.message } finally { loading.value = false } }
function openOrder(order) { selectedOrder.value = order }
async function handleLogout() { try { await logout() } catch {} clearSession(); await router.replace('/login') }
onMounted(loadOrders)
</script>

