or:#a4b0bf;font-size:11px}.orders-panel{overflow:hidden;border:1px solid #e5ebf3;border-radius:15px;background:#fff}.order-row{display:grid;grid-template-columns:1.7fr .7fr .55fr .65fr;min-height:105px;padding:20px 24px;align-items:center;gap:15px;border-bottom:1px solid #eef1f5}.order-row:last-child{border-bottom:0}.order-main{display:flex;align-items:center;gap:15px}.order-icon{display:grid;width:50px;height:50px;place-items:center;border-radius:14px;font-size:24px;background:#edf4ff}.order-main h2{margin:0 0 7px;color:#33435b;font-size:14px;font-weight:650}.order-main p,.order-main time{display:block;margin:0;color:#9aa8ba;font-size:11px}.order-main time{margin-top:5px}.order-price{display:flex;flex-direction:column;gap:6px}.order-price span{color:#a0adbd;font-size:11px}.order-price strong{color:#e65e66;font-size:17px}.order-status{display:flex;align-items:center;gap:7px;font-size:12px}.order-status i{width:7px;height:7px;border-radius:50%}.order-status.paid{color:#37ad78}.order-status.paid i{background:#42bf85}.order-status.waiting{color:#dc9b47}.order-status.waiting i{background:#e5a14e}.order-status.cancelled{color:#a3afbe}.order-status.cancelled i{background:#b5beca}.detail-button{display:flex;align-items:center;justify-content:flex-end;gap:3px;padding:0;border:0;color:var(--primary);font:inherit;font-size:12px;background:none;cursor:pointer}.detail-button svg{width:15px}.empty-card{padding:75px 24px;border:1px solid #e5ebf3;border-radius:15px;text-align:center;background:#fff}.empty-icon{display:grid;width:60px;height:60px;margin:0 auto 17px;place-items:center;border-radius:18px;font-size:26px;background:var(--primary-soft)}.empty-card h2{margin:0 0 8px;color:#34425a;font-size:18px}.empty-card p{margin:0 0 20px;color:#9aa8ba;font-size:13px}.empty-card a{display:inline-flex;padding:9px 17px;border-radius:8px;color:#fff;font-size:12px;text-decoration:none;background:var(--primary)}.pagination{display:flex;justify-content:center;align-items:center;gap:18px;marg